from collections import deque
R=C=20
seen=set(); q=deque()
# seed 6 and traverse 8 and 6
for r in range(R):
 for c in range(C):
  if grid[r][c]==6:
   q.append((r,c)); seen.add((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<R and 0<=nc<C and grid[nr][nc] in (6,8) and (nr,nc) not in seen:
   seen.add((nr,nc)); q.append((nr,nc))
out=[row[:] for row in grid]
for r,c in seen:
 if grid[r][c]!=8: continue
 boundary = r==0 or c==0 or r==R-1 or c==C-1
 if not boundary:
  boundary=any(grid[r+dr][c+dc]==1 for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0))
 if boundary: out[r][c]=7
print('reachable',len(seen),'of 8s',sum(x==8 for row in grid for x in row))
for row in out: print(' '.join(map(str,row)))

